import React from 'react'
import { connect } from 'react-redux'
import { Card, Row, Col, Collapse, Button, Alert, Spin } from 'antd'
import SummaryStyled from './summary.style'
import claimActions from '../../../redux/claim/actions'


const Panel = Collapse.Panel
const { getFormByBenefits, postClaim, resetReduxState } = claimActions

class Summary extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      claimType:
        window.sessionStorage.getItem('claimType') !== undefined ? window.sessionStorage.getItem('claimType') : '',
      claimId: '',
      failedPostClaim: '',
      loading: false,
      historyProps: props.location.state,
      checkClaimId:
        window.sessionStorage.getItem('claimId') !== undefined ? window.sessionStorage.getItem('claimId') : ''
    }
  }
  componentWillMount () {
    const { history, match, location } = this.props
    if (location.state === undefined) {
      history.push(`/policydetail/${match.params.id}`)
    }
  }
  componentWillReceiveProps (nextProps) {
    const { claimId, failedPostClaim } = nextProps
    if (claimId !== '') {
      this.setState({ claimId })
    }
    if (failedPostClaim !== '') {
      this.setState({ failedPostClaim })
    }
  }
  componentWillUnmount () {
    this.resetState()
  }
  resetState = () => {
    this.props.resetReduxState()
  }
  back = () => {
    const { history } = this.props
    history.goBack()
  }
  postClaim = () => {
    const { historyProps } = this.state
    this.setState({ loading: true })
    this.props.postClaim(historyProps)
    setTimeout(() => {
      this.setState({ loading: false })
      this.resetState()
    }, 3000)
  }
  render () {
    const { claimId, historyProps, failedPostClaim, checkClaimId } = this.state
    const { history } = this.props
    if (claimId !== '') {
      window.sessionStorage.setItem('claim', claimId)
      history.push({
        pathname: `${history.location.pathname}/finish`,
        state: { claimId }
      })
    }
    if (checkClaimId !== '') {
      history.push({
        pathname: `${history.location.pathname}/finish`,
        state: { claimId: checkClaimId }
      })
    }
    return (
      <SummaryStyled>
        <Row style={{ display: 'flex', justifyContent: 'center' }}>
          <Col xs={24} sm={24} md={12} lg={12} xl={12}>
            <Card>
              {failedPostClaim !== '' && (
                <div>
                  <Alert
                    style={{ marginBottom: '10px' }}
                    message=''
                    description={failedPostClaim}
                    type='error'
                    showIcon
                    closable
                  />
                </div>
              )}
              <Spin spinning={this.state.loading}>
                <Row>
                  <Col xs={24} sm={24} md={12} lg={24} xl={24}>
                    <Collapse defaultActiveKey={['1']}>
                      <Panel header='Ringkasan' key='1'>
                        <p>
                          {historyProps !== undefined
                            ? historyProps.packageName
                            : ''}
                        </p>
                      </Panel>
                    </Collapse>
                  </Col>
                </Row>
                <div style={{ marginTop: '30px' }}>
                  <Row>
                    <Col xs={7} sm={5} md={12} lg={24} xl={24}>
                      <p>
                        <strong>No Rekening</strong>
                      </p>
                    </Col>
                    <Col xs={17} sm={24} md={12} lg={24} xl={24}>
                      <p>
                        {historyProps !== undefined
                          ? historyProps.account_number
                          : ''}
                      </p>
                    </Col>
                  </Row>
                  <Row>
                    <Col xs={7} sm={5} md={12} lg={24} xl={24}>
                      <p>
                        <strong>Atas Nama</strong>
                      </p>
                    </Col>
                    <Col xs={17} sm={24} md={12} lg={24} xl={24}>
                      <p>
                        {historyProps !== undefined
                          ? historyProps.account_holder_name
                          : ''}
                      </p>
                    </Col>
                  </Row>
                </div>
                <Row>
                  <Col className='btn-container' span={24}>
                    <Button
                      className='btn-cancel'
                      style={{
                        float: 'left',
                        marginTop: '15px',
                        marginRight: '10px'
                      }}
                      onClick={this.back}
                    >
                      Kembali
                    </Button>
                    <Button
                      type='primary'
                      className='button'
                      onClick={this.postClaim}
                      style={{ float: 'right', marginTop: '15px' }}
                    >
                      Lanjut
                    </Button>
                  </Col>
                </Row>
              </Spin>
            </Card>
          </Col>
        </Row>
        <Col className='btn-container-mobile' span={24}>
          <Button
            className='btn-cancel'
            style={{ float: 'left', marginTop: '15px', marginLeft: '15px' }}
            onClick={this.back}
          >
            Kembali
          </Button>
          <Button
            type='primary'
            className='button'
            onClick={this.postClaim}
            style={{ float: 'right', marginTop: '15px', marginRight: '15px' }}
          >
            Lanjut
          </Button>
        </Col>
      </SummaryStyled>
    )
  }
}

export default connect(
  state => ({
    claimId: state.Claim.claimId,
    failedPostClaim: state.Claim.failedPostClaim
  }),
  { getFormByBenefits, postClaim, resetReduxState }
)(Summary)
